import os, re

pc = re.compile(r'contrastive', re.I)
pr = re.compile(r're-? ?rank', re.I)
hits = 0

for root, _, files in os.walk('/corpus'):
    for name in files:
        path = os.path.join(root, name)
        try:
            text = open(path, encoding='utf-8', errors='ignore').read()
        except Exception:
            continue

        for m in pc.finditer(text):
            start = max(0, m.start() - 600)
            end = min(len(text), m.end() + 600)
            if pr.search(text[start:end]):
                line = text.count('\n', 0, m.start()) + 1
                print(f'{path}:{line}')
                print(text[start:end].replace('\n', ' '))
                print('---')
                hits += 1
                if hits >= 20:
                    break
        if hits >= 20:
            break
    if hits >= 20:
        break
